import React from "react";

const MessagesList = ({ chats = [], activeId, onSelect }) => {
  return (
    <div className="divide-y">
      {chats.length === 0 && (
        <div className="p-4 text-sm text-gray-500">No conversations yet.</div>
      )}
      {chats.map((c) => (
        <button
          key={c._id}
          onClick={() => onSelect(c)}
          className={`w-full text-left p-3 hover:bg-orange-50 ${activeId === c._id ? "bg-orange-100" : ""}`}
        >
          <div className="text-sm font-medium">{c.participants?.map((p) => p.name).join(", ")}</div>
          <div className="text-xs text-gray-500 line-clamp-1">{c.lastMessage || "Start chatting"}</div>
        </button>
      ))}
    </div>
  );
};

export default MessagesList;
