import React, { useEffect, useRef, useState } from "react";
import api from "@/api/axios";
import { io } from "socket.io-client";
import { useAuth } from "@/contexts/AuthContext";

const getSocketUrl = () => (import.meta.env.VITE_API_URL || "http://localhost:3001").replace(/\/$/, "");

const ChatThread = ({ chat, onBack }) => {
  const { user } = useAuth();
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const listRef = useRef(null);
  const socketRef = useRef(null);

  // socket connect + join
  useEffect(() => {
    if (!chat?._id) return;
    const socket = io(getSocketUrl(), { transports: ["websocket"], withCredentials: true });
    socketRef.current = socket;
    socket.emit("join_chat", { chatId: chat._id });
    socket.on("new_message", (evt) => {
      if (evt.chatId === chat._id) setMessages((m) => [...m, evt.message]);
    });
    return () => {
      socket.emit("leave_chat", { chatId: chat._id });
      socket.disconnect();
      socketRef.current = null;
    };
  }, [chat?._id]);

  // initial load
  useEffect(() => {
    const load = async () => {
      if (!chat?._id) return;
      const res = await api.get(`/chat/${chat._id}/messages?limit=50`);
      setMessages(res.data.messages || []);
    };
    load();
  }, [chat?._id]);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: "smooth" });
  }, [messages]);

  const send = async (e) => {
    e.preventDefault();
    const text = input.trim();
    if (!text) return;
    setInput("");
    const { data } = await api.post(`/chat/${chat._id}/messages`, { content: text });
    setMessages((m) => [...m, data]);
  };

  const other = (chat.participants || []).find((p) => p._id !== user?._id);

  return (
    <div className="flex flex-col h-full">
      <div className="p-3 border-b flex items-center gap-2">
        {onBack && (
          <button onClick={onBack} className="px-2 py-1 text-sm border rounded-md">Back</button>
        )}
        <div className="font-medium text-sm">{other?.name || "Conversation"}</div>
      </div>
      <div ref={listRef} className="flex-1 overflow-auto p-3 space-y-2 bg-gray-50">
        {messages.map((m) => (
          <div key={m._id} className={`text-sm max-w-[80%] ${m.sender === user?._id ? "ml-auto bg-orange-100" : "mr-auto bg-white"} px-3 py-2 rounded-md shadow-sm`}>{m.content}</div>
        ))}
      </div>
      <form onSubmit={send} className="p-3 border-t flex gap-2">
        <input value={input} onChange={(e) => setInput(e.target.value)} className="flex-1 border rounded-md px-3 py-2 text-sm" placeholder="Type a message" />
        <button className="px-3 py-2 bg-orange-500 text-white rounded-md text-sm">Send</button>
      </form>
    </div>
  );
};

export default ChatThread;
